"""fp8 block-scaled GEMM for DeepSeek-V4-Pro's dense linears at decode on gfx950: out = (a * a_scale) @ (b * b_scale)^T
in bf16. a is e4m3 with an f32 scale per 128 values of a row, column-major; b is e4m3 in aiter's 16 x 16 shuffle with
an f32 scale per 128 x 128 block.

One launch of a precompiled code object (codeobjects.py), the one tuned for the call's m. Some of them split k across
workgroups: those take a scratch buffer for the partial sums, and counters that start at zero and that every launch
leaves at zero."""

import base64
import struct
import zlib

import torch

from aklr.core.jit import hsaco

from .codeobjects import KERNELS, POINTS

_PACK = {"ptr": "<Q", "u32": "<I"}
_KERNELS = {
    name: hsaco.Kernel(zlib.decompress(base64.b64decode(spec["code_object"])), spec["symbol"])
    for name, spec in KERNELS.items()
}
# the counters, by (device, kernel, argument): zero when allocated, and every launch leaves them zero
_COUNTERS = {}


def run(*, a, b, a_scale, b_scale, scale_major_mode, trans_b, operand_format, bias, out_dtype, out):
    m, k = a.shape
    n = b.shape[0]
    name = POINTS[m]
    spec = KERNELS[name]
    device = a.device
    if out is None:
        out = torch.empty(m, n, dtype=torch.bfloat16, device=device)
    values = {"XQ": a, "XS": a_scale, "W": b, "WS": b_scale, "D": out, "M": m, "N": n, "K": k}
    for arg, (kind, size) in spec.get("memory", {}).items():
        if kind == "scratch":
            values[arg] = torch.empty(size, dtype=torch.uint8, device=device)
        else:
            counters = _COUNTERS.get((device, name, arg))
            if counters is None:
                counters = torch.zeros(size, dtype=torch.uint8, device=device)
                _COUNTERS[(device, name, arg)] = counters
            values[arg] = counters
    kernarg = bytearray(spec["kernarg_bytes"])
    for arg, (kind, offset) in spec["args"].items():
        value = values[arg]
        struct.pack_into(_PACK[kind], kernarg, offset, value.data_ptr() if kind == "ptr" else value)
    _KERNELS[name].launch((spec["grid"],), (spec["block"],), kernarg, device=device)
    return out
